package cn.xinji.agentplatform.consultation.caselibrary;

import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;
import org.hamcrest.Matchers;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.test.web.servlet.MockMvc;

@SpringBootTest(properties={"consultation.storage=memory","spring.autoconfigure.exclude=org.springframework.boot.autoconfigure.jdbc.DataSourceAutoConfiguration"}) @AutoConfigureMockMvc
class CaseLibraryHttpApiTest {private static final String USER="v0-authorized-user";@Autowired MockMvc mvc;
 @Test void queriesStableFieldsWithoutInventingDocketNumbers()throws Exception{mvc.perform(get("/api/v0/case-library").header("X-V0-Actor",USER).param("caseNumber"," SYN-CASE-00013 ")).andExpect(status().isOk()).andExpect(jsonPath("$.dataMode").value("DEVELOPMENT_MIXED")).andExpect(jsonPath("$.total").value(1)).andExpect(jsonPath("$.items[0].docketNumber").doesNotExist());mvc.perform(get("/api/v0/case-library").header("X-V0-Actor",USER).param("docketNumber","SYN-CASE-00013")).andExpect(status().isOk()).andExpect(jsonPath("$.total").value(0));}
 @Test void filtersGloballyAndRejectsInvalidRanges()throws Exception{mvc.perform(get("/api/v0/case-library").header("X-V0-Actor",USER).param("ipType","商标").param("procedure","二审").param("annotationState","PUBLISHED").param("pageSize","10")).andExpect(status().isOk()).andExpect(jsonPath("$.items.length()").value(Matchers.lessThanOrEqualTo(10)));mvc.perform(get("/api/v0/case-library").header("X-V0-Actor",USER).param("decisionFrom","2025-02-01").param("decisionTo","2025-01-01")).andExpect(status().isBadRequest()).andExpect(jsonPath("$.code").value("INVALID_REQUEST"));}
 @Test void keepsProceedingsSeparateAndExposesDocumentFailures()throws Exception{mvc.perform(get("/api/v0/case-library/CASE-SYN-001").header("X-V0-Actor",USER)).andExpect(status().isOk()).andExpect(jsonPath("$.item.relations[0].relatedSourceRecordId").value("CASE-SYN-002")).andExpect(jsonPath("$.item.sourceRecordId").value("CASE-SYN-001"));mvc.perform(get("/api/v0/case-library/CASE-SYN-017/documents/v1").header("X-V0-Actor",USER)).andExpect(status().isOk()).andExpect(jsonPath("$.document.state").value("PARSE_FAILED")).andExpect(jsonPath("$.document.originalRef").exists());mvc.perform(get("/api/v0/case-library/CASE-SYN-019").header("X-V0-Actor",USER)).andExpect(status().isOk()).andExpect(jsonPath("$.item.attachments[0].state").value("PARSE_FAILED"));}
 @Test void returnsOnlyCurrentPublishedAnnotations()throws Exception{mvc.perform(get("/api/v0/case-library/CASE-SYN-010/published-annotation").header("X-V0-Actor",USER)).andExpect(status().isOk()).andExpect(jsonPath("$.annotation.state").value("PUBLISHED_AVAILABLE")).andExpect(jsonPath("$.annotation.annotation.lawReferences[0].versionState").value("VERSION_UNVERIFIED"));mvc.perform(get("/api/v0/case-library/CASE-SYN-007/published-annotation").header("X-V0-Actor",USER)).andExpect(status().isOk()).andExpect(jsonPath("$.annotation.state").value("NEEDS_REVIEW")).andExpect(jsonPath("$.annotation.annotation").doesNotExist());}
 @Test void includesImportedPublicCaseWithSourceTextAndNoGeneratedAnnotation()throws Exception{mvc.perform(get("/api/v0/case-library").header("X-V0-Actor",USER).param("docketNumber","（2022）最高法知民终2527号")).andExpect(status().isOk()).andExpect(jsonPath("$.total").value(1)).andExpect(jsonPath("$.items[0].sourceRecordId").value("6071")).andExpect(jsonPath("$.items[0].dataMode").value("PUBLIC_PILOT")).andExpect(jsonPath("$.items[0].decisionDate").doesNotExist());mvc.perform(get("/api/v0/case-library/6071/documents/SOURCE-6071").header("X-V0-Actor",USER)).andExpect(status().isOk()).andExpect(jsonPath("$.document.paragraphs[0].text").value(Matchers.containsString("中华人民共和国最高人民法院")));mvc.perform(get("/api/v0/case-library/6071/published-annotation").header("X-V0-Actor",USER)).andExpect(status().isOk()).andExpect(jsonPath("$.annotation.state").value("NO_PUBLISHED_ANNOTATION")).andExpect(jsonPath("$.annotation.annotation").doesNotExist());}
 @Test void enforcesAuthorizationAndHasNoWriteRoute()throws Exception{mvc.perform(get("/api/v0/case-library").header("X-V0-Actor","unknown")).andExpect(status().isForbidden()).andExpect(jsonPath("$.code").value("ACCESS_DENIED"));mvc.perform(post("/api/v0/case-library").header("X-V0-Actor",USER)).andExpect(status().isMethodNotAllowed());}
}
